-- =============================================================
--  Sudoku – CHẾ ĐỘ BẬC THẦY (chạy SAU anticheat.sql)
--  Supabase → SQL Editor → dán toàn bộ → Run. Chạy lại nhiều lần không sao.
--
--  Điều kiện mở khóa: lọt TOP 100 ở ÍT NHẤT 1 màn Chuyên gia bất kỳ.
--  Đã mở thì giữ vĩnh viễn (tụt hạng sau đó không bị khóa lại).
--  Máy chủ chặn start_level('master-…') nếu người chơi chưa mở khóa.
-- =============================================================

-- Cho phép mã màn master-1 … master-60
alter table public.level_scores drop constraint if exists level_scores_level_id_check;
alter table public.level_scores add constraint level_scores_level_id_check
  check (level_id ~ '^(easy|medium|hard|expert|master)-([1-9]|[1-5][0-9]|60)$');

