  set puzzle = excluded.puzzle, solution = excluded.solution;

-- Người chơi đã mở khóa
create table if not exists private.master_unlocks (
  player_id   uuid primary key,
  unlocked_at timestamptz not null default now()
);
alter table private.master_unlocks enable row level security;

-- ---------- Tiến độ mở khóa của tôi ----------
create or replace function public.master_status()
returns table (unlocked boolean, qualified integer, required integer, top integer)
language plpgsql
security definer
set search_path = public, private
as $$
declare
  uid uuid := auth.uid();
  req constant integer := 1;    -- số màn Chuyên gia phải đạt
  top_n constant integer := 100; -- phải nằm trong top này
  q integer;
begin
  if uid is null then
    return query select false, 0, req, top_n;
    return;
  end if;
  if exists (select 1 from private.master_unlocks m where m.player_id = uid) then
    return query select true, req, req, top_n;
    return;
  end if;

  -- Số màn Chuyên gia mà hạng của tôi ≤ 100
  select count(*) into q
  from public.level_scores me
  where me.player_id = uid
    and me.level_id like 'expert-%'
    and (select count(*) from public.level_scores o
          where o.level_id = me.level_id
            and (o.time_seconds < me.time_seconds
                 or (o.time_seconds = me.time_seconds and o.updated_at < me.updated_at))) < top_n;

  if q >= req then
    insert into private.master_unlocks (player_id) values (uid) on conflict do nothing;
    return query select true, q, req, top_n;
  else
    return query select false, q, req, top_n;
  end if;
end;
$$;

revoke all on function public.master_status() from public, anon;
grant execute on function public.master_status() to authenticated;

-- ---------- start_level: chặn màn Bậc thầy khi chưa mở khóa ----------
create or replace function public.start_level(p_level_id text)
returns uuid
language plpgsql
security definer
set search_path = public, private
as $$
declare
  uid uuid := auth.uid();
  tok uuid;
begin
  if uid is null then
    raise exception 'Chưa đăng nhập';
  end if;
  if not exists (select 1 from private.levels where level_id = p_level_id) then
    raise exception 'Màn không tồn tại';
  end if;
  if p_level_id like 'master-%'
     and not (select s.unlocked from public.master_status() s) then
    raise exception 'Chưa mở khóa chế độ Bậc thầy';
  end if;
  delete from private.level_sessions
   where player_id = uid
     and (level_id = p_level_id or started_at < now() - interval '2 days');
  insert into private.level_sessions (player_id, level_id)
  values (uid, p_level_id)
  returning token into tok;
  return tok;
end;
$$;

revoke all on function public.start_level(text) from public, anon;
grant execute on function public.start_level(text) to authenticated;
